const posts = $input.all();
const settings = $('Get Project Settings').first().json.settings;
const postsPerDay = Number(settings.posts_per_day);
const startHour = Number(settings.publish_start_hour);
const endHour = Number(settings.publish_end_hour);
const postsToday = Number($("Get Today's Post Count").first().json.posts_today ?? 0);
const zone = 'Europe/Warsaw';
if (!Number.isFinite(postsPerDay) || postsPerDay <= 0 || !Number.isFinite(startHour) || !Number.isFinite(endHour) || startHour < 0 || startHour > 23 || endHour < 0 || endHour > 23 || startHour >= endHour) throw new Error('Invalid publishing settings');
const now = $now.setZone(zone);
const futureScheduledReady = posts.filter(item => item.json.scheduled_at).length;
const alreadyUsedToday = Math.max(0, postsToday - futureScheduledReady);
const remainingToday = Math.max(0, Math.floor(postsPerDay) - alreadyUsedToday);
if (remainingToday === 0) return [];
const selectedPosts = posts.slice(0, remainingToday);
if (!selectedPosts.length) return [];
const dayStart = now.startOf('day');
const windowStart = dayStart.set({hour:startHour,minute:0,second:0,millisecond:0});
const windowEnd = dayStart.set({hour:endHour,minute:0,second:0,millisecond:0});
if (now >= windowEnd) return [];
const start = now < windowStart ? windowStart : now.plus({minutes:5});
const normalIntervalMinutes = windowEnd.diff(windowStart,'minutes').minutes / postsPerDay;
let intervalMinutes = normalIntervalMinutes;
if (selectedPosts.length > 1) {
  const availableMinutes = windowEnd.diff(start,'minutes').minutes;
  const requiredMinutes = normalIntervalMinutes * (selectedPosts.length - 1);
  if (requiredMinutes > availableMinutes) intervalMinutes = availableMinutes / (selectedPosts.length - 1);
}
return selectedPosts.map((item,index)=>({json:{...item.json,scheduled_at:start.plus({minutes:intervalMinutes*index}).toUTC().toISO()}}));

